// Integration fixtures are generated by SQLite itself, then independently
// SQLCipher-encrypted. No personal databases, processes or keys are accessed.
const { test } = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const fsPromises = require('node:fs/promises')
const path = require('node:path')
const crypto = require('node:crypto')
const Module = require('node:module')
const { DatabaseSync } = require('node:sqlite')
const ts = require('typescript')

const sourceModule = path.join(__dirname, 'database-crypto.ts')
const isolated = new Module(sourceModule, module)
isolated.filename = sourceModule
isolated.paths = Module._nodeModulePaths(__dirname)
isolated._compile(ts.transpileModule(fs.readFileSync(sourceModule, 'utf8'), {
  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS, esModuleInterop: true },
}).outputText, sourceModule)
const { createDatabaseSnapshot } = isolated.exports

const temporaryRoot = path.resolve(__dirname, '../../.caseboard-data/tmp')
const syntheticKey = 'b6d12d5e526dd37025c5504fc5dab53afbdad4116a8983c2f171949b3950a3e2'
const profiles = [
  { label: 'SQLCipher4 raw', pageSize: 4096, reserve: 80, digest: 'sha512', iterations: 256000, mode: 'raw' },
  { label: 'SQLCipher4 PBKDF2', pageSize: 4096, reserve: 80, digest: 'sha512', iterations: 256000, mode: 'pbkdf2' },
  { label: 'WeChat3 SHA1 raw', pageSize: 4096, reserve: 48, digest: 'sha1', iterations: 64000, mode: 'raw' },
  { label: 'WeChat3 SHA1 1024 raw', pageSize: 1024, reserve: 48, digest: 'sha1', iterations: 64000, mode: 'raw' },
]

function ownedWorkspace(t) {
  fs.mkdirSync(temporaryRoot, { recursive: true })
  const folder = fs.mkdtempSync(path.join(temporaryRoot, 'encrypted-wal-'))
  t.after(() => {
    const resolved = path.resolve(folder)
    assert.equal(path.dirname(resolved), temporaryRoot)
    assert(path.basename(resolved).startsWith('encrypted-wal-'))
    fs.rmSync(resolved, { recursive: true, force: true })
  })
  return folder
}

// SQLite stores the WAL checksum fields in big endian. Magic 0x377f0682
// selects little endian input words; 0x377f0683 selects big endian input words.
// This implementation is also checked against every original SQLite frame
// before it is used to write checksums for our encrypted fixture.
function checksum(bytes, previous, littleEndian) {
  assert.equal(bytes.length % 8, 0)
  let [first, second] = previous
  for (let offset = 0; offset < bytes.length; offset += 8) {
    const left = littleEndian ? bytes.readUInt32LE(offset) : bytes.readUInt32BE(offset)
    const right = littleEndian ? bytes.readUInt32LE(offset + 4) : bytes.readUInt32BE(offset + 4)
    first = (first + left + second) >>> 0
    second = (second + right + first) >>> 0
  }
  return [first, second]
}

function walLayout(wal, pageSize) {
  assert(wal.length >= 32)
  const magic = wal.readUInt32BE(0)
  assert([0x377f0682, 0x377f0683].includes(magic))
  assert.equal(wal.readUInt32BE(4), 3007000)
  assert.equal(wal.readUInt32BE(8), pageSize)
  assert.equal((wal.length - 32) % (pageSize + 24), 0)
  return { littleEndian: magic === 0x377f0682, count: (wal.length - 32) / (pageSize + 24) }
}

function walkChecksums(wal, pageSize, rewrite = false) {
  const { littleEndian, count } = walLayout(wal, pageSize)
  let rolling = checksum(wal.subarray(0, 24), [0, 0], littleEndian)
  const checkOrWrite = (offset, value) => {
    if (rewrite) wal.writeUInt32BE(value, offset)
    else assert.equal(wal.readUInt32BE(offset), value, `SQLite rolling checksum at byte ${offset}`)
  }
  checkOrWrite(24, rolling[0]); checkOrWrite(28, rolling[1])
  for (let index = 0; index < count; index++) {
    const offset = 32 + index * (pageSize + 24)
    assert(wal.subarray(offset + 8, offset + 16).equals(wal.subarray(16, 24)), 'frame salts match this WAL generation')
    assert(wal.readUInt32BE(offset) > 0)
    rolling = checksum(wal.subarray(offset, offset + 8), rolling, littleEndian)
    rolling = checksum(wal.subarray(offset + 24, offset + 24 + pageSize), rolling, littleEndian)
    checkOrWrite(offset + 16, rolling[0]); checkOrWrite(offset + 20, rolling[1])
  }
  return count
}

function normalizedRows(db) {
  const statement = db.prepare('SELECT id, body, server_id FROM messages ORDER BY id')
  statement.setReadBigInts(true)
  return statement.all().map(row => ({ id: String(row.id), body: row.body, serverId: String(row.server_id) }))
}

function sqliteWalFixture(folder, profile, { shrink = false, largeRows = 0 } = {}) {
  const filename = path.join(folder, 'sqlite-generated.db')
  let db = new DatabaseSync(filename)
  db.exec(`PRAGMA page_size=${profile.pageSize}; VACUUM;`)
  db.close()
  const bootstrap = fs.readFileSync(filename)
  assert.equal(bootstrap.readUInt16BE(103), 0)
  bootstrap[20] = profile.reserve
  bootstrap.writeUInt16BE(profile.pageSize - profile.reserve, 105)
  fs.writeFileSync(filename, bootstrap)
  db = new DatabaseSync(filename)
  try {
    db.exec('PRAGMA journal_mode=WAL; PRAGMA wal_autocheckpoint=0; CREATE TABLE messages (id INTEGER PRIMARY KEY, body TEXT NOT NULL, server_id INTEGER NOT NULL);')
    const insert = db.prepare('INSERT INTO messages VALUES (?, ?, ?)')
    insert.run(1, '主库中的旧消息', 6116895530414915991n)
    insert.run(2, '稍后删除的消息', 6116895530414915992n)
    insert.run(3, '稍后更新的消息', 6116895530414915993n)
    db.exec('PRAGMA wal_checkpoint(TRUNCATE);')
    assert.equal(fs.statSync(`${filename}-wal`).size, 0)
    const base = fs.readFileSync(filename)
    const before = normalizedRows(db)
    db.exec("BEGIN; UPDATE messages SET body='第一次 WAL 更新' WHERE id=1;")
    insert.run(4, 'WAL 新增消息', 9223372036854775806n)
    db.exec('COMMIT;')
    db.exec('BEGIN;')
    db.prepare('UPDATE messages SET body=? WHERE id=1').run('多次提交后最终版本：' + '忆'.repeat(2600))
    insert.run(5, '仅存在 WAL 中的新溢出页：' + '卷'.repeat(4200), 9223372036854775807n)
    db.exec('COMMIT; BEGIN; DELETE FROM messages WHERE id=2;')
    db.prepare('UPDATE messages SET body=? WHERE id=3').run('最后一次提交的更新')
    db.exec('COMMIT;')
    if (largeRows) {
      db.exec('BEGIN;')
      for (let index = 0; index < largeRows; index++) insert.run(100 + index, `跨批次 WAL 消息 ${index}：${'卷'.repeat(2000)}`, 6116895530415000000n + BigInt(index))
      db.exec('COMMIT;')
    }
    if (shrink) {
      db.exec("DELETE FROM messages WHERE id=5; UPDATE messages SET body='缩库后的最终消息' WHERE id=1; VACUUM;")
    }
    assert.equal(db.prepare('PRAGMA integrity_check').get().integrity_check, 'ok')
    const expected = normalizedRows(db)
    const wal = fs.readFileSync(`${filename}-wal`)
    const shm = fs.readFileSync(`${filename}-shm`)
    const count = walkChecksums(wal, profile.pageSize)
    const pageNumbers = Array.from({ length: count }, (_, index) => wal.readUInt32BE(32 + index * (profile.pageSize + 24)))
    assert(pageNumbers.some((page, index) => pageNumbers.indexOf(page) !== index), 'fixture must rewrite the same database page in multiple frames')
    assert(pageNumbers.some(page => page > base.length / profile.pageSize), 'fixture must contain pages that exist only in WAL')
    assert.deepEqual(fs.readFileSync(filename), base, 'SQLite has not checkpointed any of the new commits into main DB')
    assert.notDeepEqual(before, expected)
    return { base, wal, shm, expected, pageNumbers, before }
  } finally { db.close() }
}

function encryptor(profile) {
  const salt = crypto.randomBytes(16)
  const raw = Buffer.from(syntheticKey, 'hex')
  const key = profile.mode === 'raw' ? raw : crypto.pbkdf2Sync(raw, salt, profile.iterations, 32, profile.digest)
  const macSalt = Buffer.from([...salt].map(byte => byte ^ 0x3a))
  const macKey = crypto.pbkdf2Sync(key, macSalt, 2, 32, profile.digest)
  return {
    page(plain, pageNumber) {
      assert.equal(plain.length, profile.pageSize)
      const skip = pageNumber === 1 ? 16 : 0
      const reserveStart = profile.pageSize - profile.reserve
      const iv = crypto.randomBytes(16)
      const aes = crypto.createCipheriv('aes-256-cbc', key, iv)
      aes.setAutoPadding(false)
      const cipher = Buffer.concat([aes.update(plain.subarray(skip, reserveStart)), aes.final()])
      const output = Buffer.alloc(profile.pageSize)
      if (pageNumber === 1) salt.copy(output)
      cipher.copy(output, skip)
      iv.copy(output, reserveStart)
      const number = Buffer.alloc(4)
      // HMAC uses the actual SQLite page number, never the WAL frame index.
      number.writeUInt32LE(pageNumber)
      crypto.createHmac(profile.digest, macKey).update(cipher).update(iv).update(number).digest().copy(output, reserveStart + 16)
      return output
    },
    dispose() { raw.fill(0); key.fill(0); macKey.fill(0); macSalt.fill(0) },
  }
}

function encryptedFixture(folder, profile, { uncommittedTail = false, shrink = false, bigEndian = false, largeRows = 0 } = {}) {
  const generated = sqliteWalFixture(folder, profile, { shrink, largeRows })
  const cipher = encryptor(profile)
  try {
    const base = Buffer.alloc(generated.base.length)
    for (let offset = 0; offset < base.length; offset += profile.pageSize) {
      cipher.page(generated.base.subarray(offset, offset + profile.pageSize), 1 + offset / profile.pageSize).copy(base, offset)
    }
    let wal = Buffer.from(generated.wal)
    const frameSize = profile.pageSize + 24
    for (let offset = 32; offset < wal.length; offset += frameSize) {
      const pageNumber = wal.readUInt32BE(offset)
      cipher.page(generated.wal.subarray(offset + 24, offset + frameSize), pageNumber).copy(wal, offset + 24)
    }
    if (uncommittedTail) {
      // A valid encrypted rewrite of table root page 2, containing stale rows,
      // is deliberately left uncommitted. It must never reach the snapshot.
      const tail = Buffer.alloc(frameSize)
      tail.writeUInt32BE(2, 0)
      tail.writeUInt32BE(0, 4)
      wal.copy(tail, 8, 16, 24)
      cipher.page(generated.base.subarray(profile.pageSize, 2 * profile.pageSize), 2).copy(tail, 24)
      wal = Buffer.concat([wal, tail])
    }
    if (bigEndian) wal.writeUInt32BE(0x377f0683, 0)
    walkChecksums(wal, profile.pageSize, true)
    walkChecksums(wal, profile.pageSize)
    const sourcePath = path.join(folder, 'encrypted.db')
    fs.writeFileSync(sourcePath, base)
    fs.writeFileSync(`${sourcePath}-wal`, wal)
    fs.writeFileSync(`${sourcePath}-shm`, generated.shm)
    return { ...generated, sourcePath, encryptedWal: wal, encryptedBase: base }
  } finally { cipher.dispose() }
}

function captureSource(sourcePath) {
  return ['', '-wal', '-shm'].map(suffix => fs.readFileSync(`${sourcePath}${suffix}`))
}
function assertSourceUnchanged(sourcePath, before) {
  for (const [index, suffix] of ['', '-wal', '-shm'].entries()) {
    assert.deepEqual(fs.readFileSync(`${sourcePath}${suffix}`), before[index], `source ${suffix || 'DB'} bytes stay unchanged`)
  }
}
function assertSnapshot(destinationPath, expected, reserve) {
  const bytes = fs.readFileSync(destinationPath)
  assert.equal(bytes.subarray(0, 16).toString(), 'SQLite format 3\0')
  assert.equal(bytes[18], 1)
  assert.equal(bytes[19], 1)
  assert.equal(bytes[20], reserve)
  const db = new DatabaseSync(destinationPath, { readOnly: true })
  try {
    assert.deepEqual(normalizedRows(db), expected)
    assert.equal(db.prepare('PRAGMA integrity_check').get().integrity_check, 'ok')
  } finally { db.close() }
}
function assertNoPrivateCopies(folder) {
  assert.equal(fs.readdirSync(folder).some(name => name.startsWith('.database-snapshot-')), false)
}

// Checkpoints may leave the whole old WAL allocation in place. SQLite then
// replaces the header and a small prefix with a new generation, without
// truncating the old frames. Verify that behavior using SQLite itself before
// encrypting the page payloads for the snapshot reader.
function sqliteResetWalFixture(folder, profile, { beforeFirstFrame = false } = {}) {
  const filename = path.join(folder, 'sqlite-reset-generated.db')
  let db = new DatabaseSync(filename)
  db.exec(`PRAGMA page_size=${profile.pageSize}; VACUUM;`)
  db.close()
  const bootstrap = fs.readFileSync(filename)
  bootstrap[20] = profile.reserve
  bootstrap.writeUInt16BE(profile.pageSize - profile.reserve, 105)
  fs.writeFileSync(filename, bootstrap)
  db = new DatabaseSync(filename)
  try {
    db.exec('PRAGMA journal_mode=WAL; PRAGMA wal_autocheckpoint=0; CREATE TABLE messages (id INTEGER PRIMARY KEY, body TEXT NOT NULL, server_id INTEGER NOT NULL); BEGIN;')
    const insert = db.prepare('INSERT INTO messages VALUES (?, ?, ?)')
    insert.run(1, '已经写回主库的旧消息', 9223372036854775807n)
    for (let index = 2; index < 10; index++) insert.run(index, `已经完成检查点的第 ${index} 条：${'卷'.repeat(2200)}`, 6116895530414915991n + BigInt(index))
    db.exec('COMMIT;')
    const oldWal = fs.readFileSync(`${filename}-wal`)
    walkChecksums(oldWal, profile.pageSize)
    const checkpoint = db.prepare('PRAGMA wal_checkpoint(RESTART)').get()
    assert.equal(checkpoint.busy, 0)
    assert.equal(checkpoint.log, checkpoint.checkpointed)
    assert(fs.readFileSync(`${filename}-wal`).equals(oldWal), 'RESTART does not truncate or erase the old WAL bytes')
    const base = fs.readFileSync(filename)
    const checkpointRows = normalizedRows(db)
    db.prepare('UPDATE messages SET body=? WHERE id=1').run('新一代 WAL 的已提交消息')
    const newRows = normalizedRows(db)
    const liveWal = fs.readFileSync(`${filename}-wal`)
    assert.equal(liveWal.length, oldWal.length, 'the shorter second generation reuses the existing WAL allocation')
    assert(!liveWal.subarray(16, 24).equals(oldWal.subarray(16, 24)), 'SQLite changed the WAL generation salt')
    const frameSize = profile.pageSize + 24
    let validFrames = 0
    for (let offset = 32; offset + frameSize <= liveWal.length; offset += frameSize) {
      if (!liveWal.subarray(offset + 8, offset + 16).equals(liveWal.subarray(16, 24))) break
      validFrames++
    }
    assert(validFrames > 0)
    assert(validFrames < (liveWal.length - 32) / frameSize, 'real SQLite reset leaves old-generation frames after the new commit')
    walkChecksums(liveWal.subarray(0, 32 + validFrames * frameSize), profile.pageSize)
    // This is the crash-safe state after the new header was persisted, before
    // the first new frame replaced the old generation. It has no WAL commit.
    const wal = beforeFirstFrame ? Buffer.concat([liveWal.subarray(0, 32), oldWal.subarray(32)]) : liveWal
    const expected = beforeFirstFrame ? checkpointRows : newRows
    const oraclePath = path.join(folder, 'native-sqlite-reset-oracle.db')
    fs.writeFileSync(oraclePath, base)
    fs.writeFileSync(`${oraclePath}-wal`, wal)
    const oracle = new DatabaseSync(oraclePath, { readOnly: true })
    try {
      assert.deepEqual(normalizedRows(oracle), expected, 'native SQLite recovery is the plaintext oracle for reset semantics')
      assert.equal(oracle.prepare('PRAGMA integrity_check').get().integrity_check, 'ok')
    } finally { oracle.close() }
    return { base, wal, expected, validFrames: beforeFirstFrame ? 0 : validFrames, shm: fs.readFileSync(`${filename}-shm`) }
  } finally { db.close() }
}

function encryptedResetWalFixture(folder, profile, options) {
  const generated = sqliteResetWalFixture(folder, profile, options)
  const cipher = encryptor(profile)
  try {
    const base = Buffer.alloc(generated.base.length)
    for (let offset = 0; offset < base.length; offset += profile.pageSize) {
      cipher.page(generated.base.subarray(offset, offset + profile.pageSize), 1 + offset / profile.pageSize).copy(base, offset)
    }
    const wal = Buffer.from(generated.wal)
    const frameSize = profile.pageSize + 24
    for (let offset = 32; offset + frameSize <= wal.length; offset += frameSize) {
      cipher.page(generated.wal.subarray(offset + 24, offset + frameSize), wal.readUInt32BE(offset)).copy(wal, offset + 24)
    }
    walkChecksums(wal.subarray(0, 32 + generated.validFrames * frameSize), profile.pageSize, true)
    const sourcePath = path.join(folder, 'encrypted-reset.db')
    fs.writeFileSync(sourcePath, base)
    fs.writeFileSync(`${sourcePath}-wal`, wal)
    fs.writeFileSync(`${sourcePath}-shm`, generated.shm)
    return { ...generated, sourcePath, encryptedWal: wal, encryptedBase: base }
  } finally { cipher.dispose() }
}

for (const profile of [profiles[0], profiles[3]]) {
  test(`${profile.label}: reset WAL with a valid new header and only old-generation frames reads the authenticated checkpointed main DB`, async t => {
    const folder = ownedWorkspace(t)
    const fixture = encryptedResetWalFixture(folder, profile, { beforeFirstFrame: true })
    assert(!fixture.encryptedWal.subarray(16, 24).equals(fixture.encryptedWal.subarray(40, 48)))
    const before = captureSource(fixture.sourcePath)
    const destinationPath = path.join(folder, 'reset-before-first-frame.db')
    const result = await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
    assert.equal(result.encrypted, true)
    assert.equal(result.walApplied, false)
    assert.equal(result.partial, false, 'an ordinary reset boundary is not damaged or incomplete data')
    assertSnapshot(destinationPath, fixture.expected, profile.reserve)
    assertSourceUnchanged(fixture.sourcePath, before)
    assertNoPrivateCopies(folder)
  })

  test(`${profile.label}: real SQLite WAL reset applies the new-generation commit and ignores the old-generation tail`, async t => {
    const folder = ownedWorkspace(t)
    const fixture = encryptedResetWalFixture(folder, profile)
    const before = captureSource(fixture.sourcePath)
    const destinationPath = path.join(folder, 'reset-after-new-commit.db')
    const result = await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
    assert.equal(result.encrypted, true)
    assert.equal(result.walApplied, true)
    assert.equal(result.partial, false, 'old-generation frames are normal reuse, not an incomplete recovery')
    assertSnapshot(destinationPath, fixture.expected, profile.reserve)
    assertSourceUnchanged(fixture.sourcePath, before)
    assertNoPrivateCopies(folder)
  })
}

test('old-generation WAL reset boundary cannot bypass header checksums or main DB page authentication', async t => {
  const folder = ownedWorkspace(t), profile = profiles[0]
  const fixture = encryptedResetWalFixture(folder, profile, { beforeFirstFrame: true })
  for (const problem of ['header-checksum', 'main-first-page-authentication', 'main-table-page-authentication']) {
    const changedBase = Buffer.from(fixture.encryptedBase)
    const changedWal = Buffer.from(fixture.encryptedWal)
    if (problem === 'header-checksum') changedWal[24] ^= 1
    if (problem === 'main-first-page-authentication') changedBase[100] ^= 1
    if (problem === 'main-table-page-authentication') changedBase[profile.pageSize + 100] ^= 1
    fs.writeFileSync(fixture.sourcePath, changedBase)
    fs.writeFileSync(`${fixture.sourcePath}-wal`, changedWal)
    const before = captureSource(fixture.sourcePath)
    const destinationPath = path.join(folder, `reset-refused-${problem}.db`)
    await assert.rejects(createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey }), /WAL|校验|认证|密钥|格式/)
    assert.equal(fs.existsSync(destinationPath), false)
    assertSourceUnchanged(fixture.sourcePath, before)
    assertNoPrivateCopies(folder)
  }
})

for (const profile of profiles) {
  test(`${profile.label}: encrypted WAL applies committed inserts, repeated updates and exact 64-bit IDs without changing DB/WAL/SHM`, async t => {
    const folder = ownedWorkspace(t)
    const fixture = encryptedFixture(folder, profile)
    const before = captureSource(fixture.sourcePath)
    const destinationPath = path.join(folder, 'snapshot.db')
    const result = await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
    assert.equal(result.encrypted, true)
    assert.equal(result.walApplied, true)
    assert.deepEqual(result.warnings, [])
    assertSnapshot(destinationPath, fixture.expected, profile.reserve)
    assertSourceUnchanged(fixture.sourcePath, before)
    assertNoPrivateCopies(folder)
  })
}

test('multi-megabyte encrypted WAL preserves every row across IO batches and authenticates late frames', async t => {
  const folder = ownedWorkspace(t), profile = profiles[0]
  const fixture = encryptedFixture(folder, profile, { largeRows: 400 })
  assert(fixture.encryptedWal.length > 2 * 1024 * 1024)
  const before = captureSource(fixture.sourcePath)
  const destinationPath = path.join(folder, 'large-snapshot.db')
  await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
  assertSnapshot(destinationPath, fixture.expected, profile.reserve)
  assertSourceUnchanged(fixture.sourcePath, before)
  const damaged = Buffer.from(fixture.encryptedWal)
  const lateFrame = 32 + 300 * (profile.pageSize + 24)
  damaged[lateFrame + 24 + 100] ^= 0x40
  walkChecksums(damaged, profile.pageSize, true)
  fs.writeFileSync(`${fixture.sourcePath}-wal`, damaged)
  const refused = path.join(folder, 'must-not-exist.db')
  await assert.rejects(createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath: refused, key: syntheticKey }), /WAL.*认证/)
  assert.equal(fs.existsSync(refused), false)
  assertNoPrivateCopies(folder)
})

test('valid encrypted WAL frames after the final commit are not applied', async t => {
  const folder = ownedWorkspace(t)
  const profile = profiles[0]
  const fixture = encryptedFixture(folder, profile, { uncommittedTail: true })
  const before = captureSource(fixture.sourcePath)
  const destinationPath = path.join(folder, 'committed-only.db')
  const result = await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
  assert.equal(result.walApplied, true)
  assertSnapshot(destinationPath, fixture.expected, profile.reserve)
  assertSourceUnchanged(fixture.sourcePath, before)
  assertNoPrivateCopies(folder)
})

test('encrypted WAL accepts the documented big endian rolling checksum variant', async t => {
  const folder = ownedWorkspace(t)
  const profile = profiles[0]
  const fixture = encryptedFixture(folder, profile, { bigEndian: true })
  const before = captureSource(fixture.sourcePath)
  const destinationPath = path.join(folder, 'big-endian.db')
  const result = await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
  assert.equal(result.walApplied, true)
  assert.deepEqual(result.warnings, [])
  assertSnapshot(destinationPath, fixture.expected, profile.reserve)
  assertSourceUnchanged(fixture.sourcePath, before)
})

test('WAL VACUUM commit truncates obsolete pages from earlier larger transactions', async t => {
  const folder = ownedWorkspace(t)
  const profile = profiles[0]
  const fixture = encryptedFixture(folder, profile, { shrink: true })
  const frameSize = profile.pageSize + 24
  const commits = Array.from({ length: (fixture.wal.length - 32) / frameSize }, (_, index) => fixture.wal.readUInt32BE(32 + index * frameSize + 4)).filter(Boolean)
  assert(Math.max(...commits) > commits.at(-1), 'fixture includes a real committed shrinking VACUUM')
  const before = captureSource(fixture.sourcePath)
  const destinationPath = path.join(folder, 'shrunk.db')
  await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
  assert.equal(fs.statSync(destinationPath).size, commits.at(-1) * profile.pageSize)
  assertSnapshot(destinationPath, fixture.expected, profile.reserve)
  assertSourceUnchanged(fixture.sourcePath, before)
})

test('damaged or truncated uncommitted tail recovers every earlier valid commit with an explicit incomplete warning', async t => {
  const folder = ownedWorkspace(t)
  const profile = profiles[0]
  const fixture = encryptedFixture(folder, profile)
  const frameSize = profile.pageSize + 24
  const tail = Buffer.from(fixture.encryptedWal.subarray(fixture.encryptedWal.length - frameSize))
  tail.writeUInt32BE(0, 4) // This appended frame never commits a transaction.
  const damaged = Buffer.concat([fixture.encryptedWal, tail])
  walkChecksums(damaged, profile.pageSize, true)
  damaged[fixture.encryptedWal.length + 16] ^= 1
  for (const problem of ['checksum', 'truncated']) {
    fs.writeFileSync(`${fixture.sourcePath}-wal`, problem === 'checksum' ? damaged : damaged.subarray(0, damaged.length - 37))
    const before = captureSource(fixture.sourcePath)
    const destinationPath = path.join(folder, `partial-tail-${problem}.db`)
    const result = await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
    assert.equal(result.encrypted, true)
    assert.equal(result.walApplied, true)
    assert(result.warnings.some(warning => /不完整/.test(warning)), 'partial WAL coverage must be explicit')
    assertSnapshot(destinationPath, fixture.expected, profile.reserve)
    assertSourceUnchanged(fixture.sourcePath, before)
    assertNoPrivateCopies(folder)
  }
})

test('truncated or corrupt encrypted WAL cannot be reported as a complete successful snapshot', async t => {
  const folder = ownedWorkspace(t)
  const profile = profiles[0]
  const fixture = encryptedFixture(folder, profile)
  const valid = Buffer.from(fixture.encryptedWal)
  for (const problem of ['truncated-frame', 'header-checksum', 'frame-checksum', 'authenticated-frame', 'frame-salt']) {
    await t.test(problem, async () => {
      let changed = Buffer.from(valid)
      if (problem === 'truncated-frame') changed = changed.subarray(0, changed.length - 37)
      if (problem === 'header-checksum') changed[24] ^= 1
      if (problem === 'frame-checksum') changed[32 + 24 + 100] ^= 1
      if (problem === 'authenticated-frame') {
        changed[32 + 24 + 100] ^= 1
        walkChecksums(changed, profile.pageSize, true)
      }
      if (problem === 'frame-salt') changed[32 + 8] ^= 1
      fs.writeFileSync(`${fixture.sourcePath}-wal`, changed)
      const before = captureSource(fixture.sourcePath)
      const destinationPath = path.join(folder, `broken-${problem}.db`)
      let result
      try {
        result = await createDatabaseSnapshot({ sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey })
      } catch (error) {
        assert.match(error.message, /WAL|校验|认证|格式/i)
        assert.equal(fs.existsSync(destinationPath), false)
      }
      if (result) {
        assert(result.warnings.some(warning => /WAL|截断|损坏|校验|认证/i.test(warning)), 'partial recovery must explicitly warn about incomplete WAL coverage')
      }
      assertSourceUnchanged(fixture.sourcePath, before)
      assertNoPrivateCopies(folder)
    })
  }
})

test('cancelling encrypted DB/WAL recovery removes destination and every private staging copy', async t => {
  const folder = ownedWorkspace(t)
  const fixture = encryptedFixture(folder, profiles[0])
  const before = captureSource(fixture.sourcePath)
  for (const preCancelled of [true, false]) {
    const control = new AbortController()
    if (preCancelled) control.abort()
    const destinationPath = path.join(folder, `cancel-${preCancelled}.db`)
    await assert.rejects(createDatabaseSnapshot({
      sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey, signal: control.signal,
      onProgress(done) { if (done > 0) control.abort() },
    }), { name: 'AbortError' })
    assert.equal(fs.existsSync(destinationPath), false)
    assertSourceUnchanged(fixture.sourcePath, before)
    assertNoPrivateCopies(folder)
  }
})

test('cancellation specifically during encrypted WAL replay cleans the output and private copies without changing source files', async t => {
  const folder = ownedWorkspace(t)
  const fixture = encryptedFixture(folder, profiles[0])
  const before = captureSource(fixture.sourcePath)
  const destinationPath = path.join(folder, 'cancel-wal.db')
  const control = new AbortController()
  let cancelledInWal = false
  await assert.rejects(createDatabaseSnapshot({
    sourcePath: fixture.sourcePath, destinationPath, key: syntheticKey, signal: control.signal,
    onProgress(done, total) {
      if (done > fixture.encryptedBase.length) {
        assert(total > fixture.encryptedBase.length, 'progress includes the committed WAL page bytes')
        cancelledInWal = true
        control.abort()
      }
    },
  }), { name: 'AbortError' })
  assert.equal(cancelledInWal, true)
  assert.equal(fs.existsSync(destinationPath), false)
  assertSourceUnchanged(fixture.sourcePath, before)
  assertNoPrivateCopies(folder)
})

test('same-size source rewrites with unchanged reported Windows metadata are rejected after three content checks', async t => {
  const folder = ownedWorkspace(t)
  const fixture = encryptedFixture(folder, profiles[0])
  const before = captureSource(fixture.sourcePath)
  const sourcePath = path.resolve(fixture.sourcePath)
  const destinationPath = path.join(folder, 'unchanged-metadata.db')
  const originalStat = fsPromises.stat
  const originalCopyFile = fsPromises.copyFile
  const frozen = new Map(await Promise.all([sourcePath, `${sourcePath}-wal`].map(async filename => [filename, await originalStat(filename, { bigint: true })])))
  let sourceCopies = 0
  try {
    fsPromises.stat = async function (filename, ...options) {
      const fixed = frozen.get(path.resolve(String(filename)))
      return fixed ?? originalStat.call(this, filename, ...options)
    }
    fsPromises.copyFile = async function (from, to, ...options) {
      await originalCopyFile.call(this, from, to, ...options)
      if (path.resolve(String(from)) === sourcePath) {
        sourceCopies++
        // Only this hook mutates the synthetic source. Toggle one byte in
        // place, after main DB copying, without changing its size or identity.
        const byte = Buffer.from([before[0][32] ^ (sourceCopies % 2)])
        const file = fs.openSync(sourcePath, 'r+')
        try { fs.writeSync(file, byte, 0, 1, 32) } finally { fs.closeSync(file) }
      }
    }
    await assert.rejects(createDatabaseSnapshot({ sourcePath, destinationPath, key: syntheticKey }), /变化|一致快照|WAL/)
    assert.equal(sourceCopies, 3, 'content mismatch must exhaust the three consistent-copy attempts')
  } finally {
    fsPromises.stat = originalStat
    fsPromises.copyFile = originalCopyFile
  }
  assert.equal(fs.existsSync(destinationPath), false)
  const expectedSource = Buffer.from(before[0])
  expectedSource[32] ^= 1 // Three test-owned toggles leave precisely this byte changed.
  assert.deepEqual(fs.readFileSync(sourcePath), expectedSource)
  assert.deepEqual(fs.readFileSync(`${sourcePath}-wal`), before[1])
  assert.deepEqual(fs.readFileSync(`${sourcePath}-shm`), before[2])
  assertNoPrivateCopies(folder)
})
